WITH filtered AS (SELECT *, SUBSTRING(location, 1, 2) AS location_prefix, COALESCE(dept_name, 'N/A') AS dept_name_filled FROM departments WHERE location IN ('New York', 'Chiang Mai', 'London')), latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name ORDER BY budget, id) AS latest_rank FROM filtered QUALIFY latest_rank = 1), metrics AS (SELECT *, MIN(budget) OVER (PARTITION BY location) AS location_min_budget, FIRST_VALUE(dept_name) IGNORE NULLS OVER (PARTITION BY location ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_dept_name, ROW_NUMBER() OVER (ORDER BY latest_rank, id) AS event_seq FROM latest), base AS (SELECT *, CONCAT_WS('/', location, dept_name) AS location_dept_name_key, COALESCE(dept_name, 'UNKNOWN') AS resolved_dept_name FROM metrics WHERE dept_name IS NOT NULL AND location IS DISTINCT FROM 'Berlin') SELECT CASE WHEN budget >= 3963000 THEN 'LARGE' ELSE 'SMALL' END AS budget_tier, COUNT_IF(location = 'Singapore') AS singapore_events, COUNT_IF(location = 'Tokyo') AS tokyo_events, MIN(event_seq) AS min_event_seq, COUNT(*) FILTER (WHERE location = 'Berlin') AS berlin_rows FROM base GROUP BY budget_tier ORDER BY min_event_seq DESC NULLS LAST;
